import openpyxl

wb = openpyxl.load_workbook('CAKE Sensitivity Analysis_vF.xlsx')
ws = wb['CAKE-US LBO']

print("=== Checking Excel tables ===")
print("\nTable titles found:")
for row in range(195, 235):
    for col in range(1, 16):
        cell = ws.cell(row=row, column=col)
        if cell.value and isinstance(cell.value, str) and 'Sensitivity Table' in str(cell.value):
            print(f"  Row {row}, Col {col}: {cell.value}")

print("\nCenter cells (blue fill check):")
for row in range(195, 235):
    for col in range(3, 12):
        cell = ws.cell(row=row, column=col)
        if cell.fill and cell.fill.start_color and cell.fill.start_color.rgb:
            rgb = str(cell.fill.start_color.rgb)
            if '4472C4' in rgb:
                print(f"  Blue cell at {cell.coordinate}: {cell.value}")

print("\nOriginal model area check (row 187-194):")
for row in range(187, 195):
    vals = []
    for col in range(1, 12):
        v = ws.cell(row=row, column=col).value
        if v is not None:
            vals.append(f"{v}")
    if vals:
        print(f"  Row {row}: {' | '.join(vals[:5])}")

print("\nExcel file validation complete")

# Check PPTX
from pptx import Presentation
prs = Presentation('CAKE Sensitivity Analysis_vF.pptx')
print(f"\n=== PPTX Check ===")
print(f"Slides: {len(prs.slides)}")
for i, slide in enumerate(prs.slides):
    print(f"\nSlide {i+1}:")
    for shape in slide.shapes:
        if shape.has_text_frame:
            text = shape.text_frame.text[:100]
            if text.strip():
                print(f"  [{shape.shape_type}] {text}...")
        if shape.has_table:
            table = shape.table
            print(f"  [TABLE] {table.rows.__len__()} rows x {len(table.columns)} cols")
            # Check center cell
            center = table.cell(3, 3)
            print(f"  Center cell: {center.text}")
